alter type public.order_status add value if not exists 'delivery_failed';
alter type public.order_status add value if not exists 'rescheduled';
alter type public.order_status add value if not exists 'return_in_transit';
alter type public.order_status add value if not exists 'returned_to_merchant';
create table if not exists public.delivery_events (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, actor_id uuid references public.profiles(id) on delete set null, event_type text not null, reason text not null, scheduled_at timestamptz, created_at timestamptz not null default now());
alter table public.delivery_events enable row level security;
revoke all on public.delivery_events from public, anon, authenticated;
create or replace function public.rider_report_delivery_issue(p_order_id uuid,p_action text,p_reason text,p_scheduled_at text default null) returns jsonb language plpgsql security definer set search_path=public as $function$ declare v_order public.orders; v_actor uuid:=auth.uid(); v_next public.order_status; v_event text; v_time timestamptz; begin if v_actor is null or not public.jwt_has_role('rider') then return jsonb_build_object('success',false,'error','Rider access required'); end if; if nullif(trim(p_reason),'') is null then return jsonb_build_object('success',false,'error','A reason is required'); end if; select * into v_order from public.orders where id=p_order_id for update; if not found then return jsonb_build_object('success',false,'error','Order not found'); end if; if v_order.rider_id is distinct from v_actor then return jsonb_build_object('success',false,'error','You are not assigned to this order'); end if; if v_order.status not in ('out_for_delivery','ready_for_pickup') then return jsonb_build_object('success',false,'error','This delivery is not active'); end if; if p_action='failed' then v_next:='delivery_failed'; v_event:='failed_delivery'; elsif p_action='reschedule' then begin v_time:=p_scheduled_at::timestamptz; exception when others then return jsonb_build_object('success',false,'error','Invalid reschedule date'); end; if v_time is null or v_time<=now() then return jsonb_build_object('success',false,'error','Reschedule time must be in the future'); end if; v_next:='rescheduled'; v_event:='rescheduled'; elsif p_action='return_to_merchant' then v_next:='return_in_transit'; v_event:='return_started'; else return jsonb_build_object('success',false,'error','Unknown delivery action'); end if; update public.orders set status=v_next where id=p_order_id; insert into public.delivery_events(order_id,actor_id,event_type,reason,scheduled_at) values(p_order_id,v_actor,v_event,trim(p_reason),v_time); return jsonb_build_object('success',true,'message','Delivery status updated.'); end; $function$; revoke execute on function public.rider_report_delivery_issue(uuid,text,text,text) from public,anon; grant execute on function public.rider_report_delivery_issue(uuid,text,text,text) to authenticated,service_role;